document.addEventListener('DOMContentLoaded',function(){const forms=document.querySelectorAll('form.js-show-loading-on-submit');if(!forms.length){console.log('Không tìm thấy form nào có class js-show-loading-on-submit');return}
forms.forEach(function(form){form.addEventListener('submit',function(e){if(!form.checkValidity()){e.preventDefault();form.reportValidity();return}
const request_des=document.getElementById('request_des');const request_des_label=document.getElementById('request_des_label');if(request_des){if(!request_des.value.trim()){e.preventDefault();request_des_label.classList.add('focus-form');request_des_label.scrollIntoView({behavior:"smooth",block:"center"});return}}
const dateInput=document.getElementById('datepicker');if(dateInput){const v=(dateInput.value||'').trim();const selectText=(dateInput.dataset.select||'').trim();if(!v||(selectText&&v===selectText)){e.preventDefault();dateInput.focus();return}}
const adult=document.getElementById('adult');const participants=document.getElementById('participants');if(adult){if(adult.value==='0'){e.preventDefault();participants.classList.add('focus');participants.scrollIntoView({behavior:"smooth",block:"center"});return}}
const adult_request=document.getElementById('request_adult');const participants_request=document.getElementById('request_participants');if(adult_request){if(adult_request.value==='0'){e.preventDefault();participants_request.classList.add('focus-form');participants_request.scrollIntoView({behavior:"smooth",block:"center"});return}}
const request_duration=document.getElementById('request_duration');const request_duration_label=document.getElementById('request_duration_label');if(request_duration){if(!request_duration.value.trim()){e.preventDefault();request_duration_label.classList.add('focus-form');request_duration_label.scrollIntoView({behavior:"smooth",block:"center"});return}}
const request_budget=document.getElementById('request_budget');const request_budget_label=document.getElementById('request_budget_label');if(request_budget){if(!request_budget.value.trim()){e.preventDefault();request_budget_label.classList.add('focus-form');request_budget_label.scrollIntoView({behavior:"smooth",block:"center"});return}}
const submitButtons=form.querySelectorAll('[type="submit"], button');submitButtons.forEach(function(btn){localStorage.setItem('booking_form_data','');btn.classList.add('active');btn.disabled=!0})})})})